SELECT 'поверхностей не собрано ни одной: приземлилось ли требование — неизвестно' AS detail WHERE NOT EXISTS (SELECT 1 FROM project_requirement_surface WHERE project_id = $1) UNION ALL SELECT r.id || ' — ни одна из поверхностей его не называет, держателя инварианта тоже нет' FROM project_requirements r WHERE r.project_id = $1 AND r.kind = 'FR' AND r.out_of_version = '' AND EXISTS (SELECT 1 FROM project_requirement_surface WHERE project_id = $1) AND NOT EXISTS (SELECT 1 FROM project_requirement_surface s WHERE s.project_id = r.project_id AND s.requirement_id = r.id) AND NOT EXISTS (SELECT 1 FROM project_requirement_holder h WHERE h.project_id = r.project_id AND h.requirement_id = r.id) AND true ORDER BY 1
